var i=`0128-khachapuri-adjaruli`;var n=`world-0128`;var t=`GE`;var r=`western-asia`;var o=4;var l=99;var s={en:`Khachapuri Adjaruli`,ua:`Хачапурі по-аджарськи`};var g={en:`Adjarian boat-shaped khachapuri with egg and butter; mozzarella and farmer cheese approximate regional Georgian cheeses unavailable in the catalog.`,ua:`Аджарський хачапурі-човник із яйцем і маслом; моцарела й домашній сир наближено замінюють регіональні грузинські сири, відсутні в каталозі.`};var h=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 60 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 60 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:60,i:[[`all-purpose-flour`,520,`g`],[`water`,290,`ml`],[`instant-yeast`,7,`g`],[`table-salt`,7,`g`],[`extra-virgin-olive-oil`,35,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:5,i:[[`mozzarella`,300,`g`],[`farmer-cheese`,300,`g`]]},{en:`Form four oval boats with high rims and a well for the cheese filling, then proof briefly.`,ua:`Сформуйте чотири овальні човники з високими бортиками та заглибленням для сиру й дайте недовго підійти.`,t:[`pre-shaping-dough`,`final-proofing`],m:18,i:[]},{en:`Bake the boats in a very hot oven until the crust is browned and cheese bubbling; crack an egg into each and return to the oven just until the whites set.`,ua:`Випікайте човники в дуже гарячій духовці до рум’яності й розплавлення сиру; додайте в кожен яйце та допечіть до схоплення білка.`,t:[`high-temperature-roasting`,`baking`],m:13,i:[[`chicken-egg`,4,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`unsalted-butter`,45,`g`]]}];var u={slug:i,id:n,country:`GE`,region:r,servings:4,minutes:99,title:s,text:g,steps:h};export{t as country,u as default,n as id,l as minutes,r as region,o as servings,i as slug,h as steps,g as text,s as title};